#!/usr/bin/env bash
set -euo pipefail
if [[ -f ci/.env ]]; then
  project="$(sed -n 's/^CI_PROJECT_NAME=//p' ci/.env)"
  [[ "$project" =~ ^sf_ci_[0-9]+_[0-9]+_[a-z0-9_]+$ ]] || { echo 'Refusing unsafe project cleanup'; exit 1; }
  # Environment file generated by prepare-env.sh, never supplied by the agent.
  set -a
  . ci/.env
  set +a
  docker compose -p "$project" -f ci/docker-compose.ci.yaml down --volumes --remove-orphans
  rm -f ci/.env
fi
